#include <stdio.h>

static long long comb(int n, int k)
{
    if (k < 0 || k > n) {
        return 0;
    }
    if (k == 0 || k == n) {
        return 1;
    }
    return comb(n - 1, k - 1) + comb(n - 1, k);
}

int main(void)
{
    int n, k;

    if (scanf("%d%d", &n, &k) != 2) {
        return 0;
    }
    printf("ways: %lld\n", comb(n, k));
    printf("fixed: %lld\n", k == 0 ? 0LL : comb(n - 1, k - 1));
    return 0;
}

