#include <stdio.h>

#define MAXN 105

static void stat(const int a[], int n, int *maxv, int *minv, double *avg)
{
    int i, sum = 0;

    *maxv = a[0];
    *minv = a[0];
    for (i = 0; i < n; i++) {
        sum += a[i];
        if (a[i] > *maxv) {
            *maxv = a[i];
        }
        if (a[i] < *minv) {
            *minv = a[i];
        }
    }
    *avg = (double)(sum - *maxv - *minv) / (double)(n - 2);
}

int main(void)
{
    int n, i;
    int a[MAXN];
    int mx, mn;
    double avg;

    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf("%d", &a[i]);
    }
    stat(a, n, &mx, &mn, &avg);
    printf("max: %d\n", mx);
    printf("min: %d\n", mn);
    printf("final: %.2f\n", avg);
    return 0;
}

