Node *relink(Node *head, int k) {
    Node dummy = {0};
    dummy.next = head;
    Node *prev = &dummy;
    while (prev->next) {
        Node *end = prev;
        for (int i = 0; i < k && end; i++)
            end = end->next;
        if (!end)
            break;
        Node *after = end->next, *p = prev->next, *tail = p, *rev = after;
        while (p != after) {
            Node *next = p->next;
            p->next = rev;
            rev = p;
            p = next;
        }
        prev->next = end;
        prev = tail;
    }
    return dummy.next;
}

