#include <stdio.h>

#define MAXL 32

static int n;
static char buf[MAXL];
static int total = 0;

static void dfs(int pos, int left, int right)
{
    if (pos == 2 * n) {
        buf[pos] = '\0';
        printf("%s\n", buf);
        total++;
        return;
    }
    if (left < n) {
        buf[pos] = '(';
        dfs(pos + 1, left + 1, right);
    }
    if (right < left) {
        buf[pos] = ')';
        dfs(pos + 1, left, right + 1);
    }
}

int main(void)
{
    if (scanf("%d", &n) != 1) {
        return 0;
    }
    dfs(0, 0, 0);
    printf("total: %d\n", total);
    return 0;
}

#include <stdio.h>
#include <string.h>
static char expression[18];
typedef struct {int ways[2];} Counts;
Counts count(int left,int right){
    Counts result={{0,0}};
    if(left==right){result.ways[expression[2*left]-'0']=1;return result;}
    for(int mid=left;mid<right;mid++){
        Counts a=count(left,mid),b=count(mid+1,right);
        char op=expression[2*mid+1];
        for(int x=0;x<2;x++)for(int y=0;y<2;y++){
            int bit=op=='&'?(x&y):op=='|'?(x|y):(x^y);
            result.ways[bit]+=a.ways[x]*b.ways[y];
        }
    }
    return result;
}
int main(void) {

    scanf("%17s",expression);
    Counts result=count(0,strlen(expression)/2);
    printf("%d\n",result.ways[1]);
    return 0;
}
